<?php use Hls\Http\View as V; if (isset($formError)): echo $this->component('alert',['message'=>$formError]); endif; ob_start(); ?>
<?php foreach ($rows as $row): ?><tr><td><?= V::escape($row['name']) ?></td><td><?= V::escape($row['email']) ?></td><td><?= V::escape($row['role_name']) ?></td><td><span class="status-badge <?= $row['active'] ? '' : 'inactive' ?>"><?= $row['active'] ? 'Aktif' : 'Nonaktif' ?></span></td><td><?php if ($access->can('users.manage') && (int)$row['id'] !== (int)$access->user['id']): ?><a href="<?= V::escape($this->url('/users?edit='.$row['id'])) ?>">Edit</a><?php endif ?></td></tr><?php endforeach ?>
<?php echo $this->component('table',['caption'=>'Pengguna fondasi','headers'=>['Nama','Email','Role','Status','Aksi'],'rowsHtml'=>ob_get_clean(),'hasRows'=>(bool)$rows]); echo $this->component('pagination',compact('pagination')); ?>
<?php if ($access->can('users.manage')): ?><form class="panel" method="post" action="<?= V::escape($this->url('/users')) ?>" <?= !empty($edit['id']) ? 'data-confirm="Simpan perubahan pengguna? Sesi lamanya akan berakhir."' : '' ?>><h2><?= !empty($edit['id']) ? 'Edit pengguna' : 'Tambah pengguna' ?></h2><?= $this->csrf() ?><input type="hidden" name="id" value="<?= V::escape($edit['id']??'') ?>"><div class="fields">
<?= $this->component('field',['name'=>'name','label'=>'Nama','required'=>true,'max'=>100,'value'=>$edit['name']??'']) ?>
<?= $this->component('field',['name'=>'email','label'=>'Email','type'=>'email','required'=>true,'max'=>190,'value'=>$edit['email']??'']) ?>
<?= $this->component('field',['name'=>'role_id','label'=>'Role','type'=>'select','required'=>true,'options'=>$roles,'value'=>$edit['role_id']??'']) ?>
<?= $this->component('field',['name'=>'password','label'=>!empty($edit['id']) ? 'Password baru (kosongkan jika tetap)' : 'Password (12–72 byte)','type'=>'password','required'=>empty($edit['id']),'min'=>12,'max'=>72,'autocomplete'=>'new-password']) ?>
</div><label class="check"><input type="checkbox" name="active" value="1" <?= !$edit || ($edit['active']??false) ? 'checked' : '' ?>>Aktif</label><fieldset><legend>Cakupan akses</legend><label class="check"><input type="checkbox" name="all_branches" value="1" <?= $edit && ($edit['all_branches']??false) ? 'checked' : '' ?>>Seluruh cabang</label><?php foreach ($branches as $branch): if (!$branch['active']) continue; ?><label class="check"><input type="checkbox" name="branches[]" value="<?= (int)$branch['id'] ?>" <?= in_array((int)$branch['id'],$selected,true) ? 'checked' : '' ?>><?= V::escape($branch['name']) ?></label><?php endforeach ?><p>Pilih seluruh cabang atau minimal satu cabang aktif. Perubahan akun mengakhiri sesi lamanya.</p></fieldset><div class="form-actions"><button class="primary" type="submit">Simpan pengguna</button><?php if ($edit): ?><a href="<?= V::escape($this->url('/users')) ?>">Batal</a><?php endif ?></div></form><?php endif ?>